{!REQUIRESCRIPT("/soap/ajax/15.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/15.0/apex.js")} 


if('{!Opportunity.StageName}' == 'Lost' ||
    '{!Opportunity.StageName}' == 'Dead'||
    '{!Opportunity.StageName}' == 'Postponed'||
    '{!Opportunity.StageName}' == '0 - Pre-Qualification'||
    '{!Opportunity.StageName}' == '1 - Qualification'||
    '{!Opportunity.StageName}' == '2 - Solution Developed'||
    '{!Opportunity.StageName}' == '3 - Solution Agreed')
{
  alert("A contract request may only be created when the opportunity is in sales stage 4, 5 or 6");
}
else{
         //look for the existance of this type of Case for the current Opportunity
         var qry = "Select Id From Case "+
                                                                      "  where Subject = 'Contract Request' "+
                                                                       "    and accountId = '{!Opportunity.AccountId}' "+
                                                                       "    and url__c  like '%{!Opportunity.Id}%' Limit 1";      

        var resultSet
                       =sforce.connection.query(qry);

         var records = resultSet.getArray("records"); 

         if (records[0] != null)
         {
                alert('A contract request has already been created for this opportunity');

          }
         else{ 
var opId= "{!Opportunity.Id}"; 
var cas = sforce.apex.execute("IME_CreateCase","createContractCase",{op_id:opId}); 

var str_NewCase = "select CaseNumber from Case where Id = '"+cas+"'"; 

var Casenum;
Casenum = sforce.connection.query(str_NewCase);

var records = Casenum.getArray("records");
if(records.length > 0)
{
var Id = records[0].CaseNumber;

alert('New case# ' + Id + ' {!$Label.IME_SC_NEW_CASE}');
}
} 
}//ENDElse
